/**
 * Generated files in a landing merge (clean-landing spec 4; L1-L3, ADR 0129): a tracked
 * file a script writes from other tracked files has its conflict resolved, never reported.
 *
 *   docs/adr/README.md            regenerated by this plugin's own `renderIndex`, and only
 *                                 when it carries the generated header (L2): no code from the
 *                                 merged tree runs, and a hand-written README stays a conflict.
 *   docs/design/<slug>/run.json   takes the writer side (L3): the feature in `land`
 *                                 ('theirs', the merged-in source), pilot in `sync` ('ours').
 *
 * Every other path, the prompt pin's included (one-integration-line A8), is answered back
 * untouched, for the caller to stop on.
 */

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

import { GENERATED_HEADER, renderIndex } from './adr-index.mjs';
import { firstLine, git } from './pilot-branch.mjs';

const INDEX = 'docs/adr/README.md';
const RUN_RECORD = /^docs\/design\/[^/]+\/run\.json$/;

/**
 * The index of the worktree `dir` when it carries the generated header as a line of its own
 * (a conflicted one still does, outside the conflicting hunk), else null: a hand-written
 * README, or one that only quotes the header, is never regenerated.
 */
function generatedIndex(dir) {
  const file = path.join(dir, INDEX);
  // A committed symlink is never followed: the regenerated index would land wherever it points.
  if (!fs.existsSync(file) || fs.lstatSync(file).isSymbolicLink()) return null;
  const text = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  return text.split('\n').includes(GENERATED_HEADER) ? { file, text } : null;
}

/** Writes the generated index over a generated one that differs; answers whether it did. */
function regenerate(dir) {
  const index = generatedIndex(dir);
  if (index === null) return false;
  const generated = renderIndex(path.dirname(index.file));
  if (index.text === generated) return false;
  fs.writeFileSync(index.file, generated, 'utf8');
  return true;
}

/** Whether a rule of `resolveGenerated` settles `path`: the ADR index or a run record. */
export const autoResolves = (file) => file === INDEX || RUN_RECORD.test(file);

/**
 * A landing conflict's line, less the caller's prefix: it names the lander that resolves the
 * stop and the kept worktree `dir`, as the tail `LANDER_LINE` parses.
 */
export const conflictLine = ({ head, onto, paths, dir }) => `${head} conflicts with ${onto} in ${paths.join(', ')}; the lander resolves in ${dir}`;

/** The kept dir at the end of a conflict line, after its last `; the lander resolves in`, so no path's name moves it. */
export const LANDER_LINE = /; the lander resolves in ((?:(?!; the lander resolves in ).)+)$/;

/** The main checkout: the first worktree `git worktree list` names. `git` is `(args) => string`. */
export const mainCheckout = (git) => git(['worktree', 'list', '--porcelain']).split(/\r?\n/)[0].replace(/^worktree /, '');

/** The worktree kept beside `checkout` for the lander, `<checkout>-<kind>-<slug>`; with no `head`, the prefix all of `kind` share. */
export const keptDir = (checkout, head = '', kind = 'land') =>
  path.join(path.dirname(checkout), `${path.basename(checkout)}-${kind}-${head.replace(/^feat\//, '').replace(/[^\w.-]+/g, '-')}`);

/** One rule per generated path: true when it resolved `file` in `dir`, false to leave it. */
function resolveOne(dir, file, side) {
  if (!autoResolves(file)) return false;
  if (file === INDEX) {
    if (generatedIndex(dir) === null) return false;
    regenerate(dir);
    return true;
  }
  if (RUN_RECORD.test(file)) {
    try {
      git(dir, 'checkout', `--${side}`, '--', file);
    } catch {
      return false; // the writer side deleted it: a stop the user decides.
    }
    return true;
  }
  return false;
}

/**
 * Resolves each generated path in `paths` inside the merge worktree `dir` and stages it;
 * `side` is the writer side, 'theirs' the merged-in source. Answers `{ resolved, left }`,
 * `left` every path no rule resolved, in the order given.
 */
export function resolveGenerated(dir, paths, { side }) {
  if (side !== 'ours' && side !== 'theirs') throw new Error(`side is 'ours' or 'theirs', not ${JSON.stringify(side)}`);
  const resolved = [];
  const left = [];
  for (const file of paths) {
    if (resolveOne(dir, file, side)) {
      git(dir, 'add', '--', file);
      resolved.push(file);
    } else {
      left.push(file);
    }
  }
  return { resolved, left };
}

/** Regenerates the index of the merged tree in `dir` when it differs, and stages it; answers whether it changed. */
export function refreshIndex(dir) {
  if (!regenerate(dir)) return false;
  git(dir, 'add', '--', INDEX);
  return true;
}

/**
 * The conflicted paths as a stop names them, with the resolver's failure when it had one, and
 * the index's generator when the index is among them.
 */
export const conflictPaths = (left, why) =>
  `${left.join(', ')}${why ? ` (generated files not resolved: ${why})` : ''}${
    left.includes(INDEX) ? `; regenerate ${INDEX} with \`node scripts/adr-index.mjs\`, never by hand` : ''
  }`;

/**
 * Merges `source` into the worktree `dir` as one commit with `message`, the generated paths
 * resolved (`side` the writer side) and the index refreshed before it: the landing's merge,
 * shared by `mergeIntoPilot` and `land`'s resume. Answers `{ left: [] }` committed, or
 * `{ left, why? }` stopped on `left` with nothing committed, `why` the resolver's failure when it
 * could not finish (then `left` is every conflicted path). Throws with `stage` 'merge' when the
 * merge stops on no path, 'commit' when the commit fails, its message git's first line.
 */
export function mergeResolved(dir, source, message, { side }) {
  try {
    // `-m` lands in MERGE_MSG, so a lander's `git commit --no-edit` keeps the landing message.
    git(dir, 'merge', '-q', '--no-ff', '--no-commit', '-m', message, source);
  } catch (err) {
    const paths = spawnSync('git', ['diff', '--name-only', '--diff-filter=U'], { cwd: dir, encoding: 'utf8', windowsHide: true }).stdout?.trim();
    if (!paths) throw Object.assign(new Error(firstLine(err)), { stage: 'merge' });
    const list = paths.split('\n');
    try {
      const { left } = resolveGenerated(dir, list, { side });
      if (left.length) return { left };
    } catch (failed) {
      return { left: list, why: firstLine(failed) };
    }
  }
  try {
    refreshIndex(dir);
    git(dir, 'commit', '-q', '-m', message);
  } catch (err) {
    throw Object.assign(new Error(firstLine(err)), { stage: 'commit' });
  }
  return { left: [] };
}
